---@class FriendInvitationSend
---@field BtnCancel                     	UnityEngine.UI.Button
---@field TxtContent                    	UnityEngine.UI.Text
---@field TxtTime                       	TMPro.TextMeshProUGUI
---@field Fill                          	UnityEngine.UI.Image
local FriendInvitationSend = Class("FriendInvitationSend")
function FriendInvitationSend:__init()
    self.timer = nil

end

function FriendInvitationSend:__delete()
    self.controller = nil
    self.timer = nil

end

function FriendInvitationSend:Awake()
    self.EventFriendPVPPromptBeRefused = Events.AddListener(Constants.EventNames.FriendPVPPromptBeRefused, Bind(self, self.FriendPVPPromptBeRefused))

end

function FriendInvitationSend:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument
        if not isNull(argument.parameters) then
            SetButtonAction(self.BtnCancel, function ()
                self:CancelInvitation()
            end)
            self:FreshBaseUI(argument.parameters)
            self:StartLeftSecond(argument.parameters.time)
            ---数据在用完后清掉
            argument.parameters = nil
        end
    end))
    return coWait
end

function FriendInvitationSend:FreshBaseUI(data)
    self.TxtContent.text = localize("正在邀请<color=#ff2dc1>[_name_]</color>进行对战！", {_name_ = data.name})
end



---进入界面开始倒计时
function FriendInvitationSend:StartLeftSecond(leftTime)
    self:StopTimer()
    self.timer = CDTimerModule:AddCD(1, function (count, id)
        if count == 0 then
            friendComponent:SetInviteState(false)
            UIModule.BackDialog()
            GameUtils.Toast(localize("请求超时"))
        end
        self.TxtTime.text = count
        self.Fill.fillAmount = count / leftTime
    end, leftTime, true, true, true)
end

function FriendInvitationSend:StopTimer()
    if not isNull(self.timer) then
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end
end

---取消邀请
function FriendInvitationSend:CancelInvitation()
    self:StopTimer()
    friendComponent:CancelInvite()
    UIModule.BackDialog()
end

---弹窗出现后发生的改变
function FriendInvitationSend:FriendPVPPromptBeRefused(result)
    if isNull(self.controller) then
        return
    end
    if not self.controller.IsShow then
        return
    end
    self:StopTimer()
    UIModule.BackDialog()

    local result = checkNumber(result)
    if result == 0 then
        GameUtils.Toast(localize("邀请被拒绝啦"))
    elseif result == 2 then
        GameUtils.Toast(localize("对方正忙着呢"))
    elseif result == 3 then
        GameUtils.Toast(localize("邀请超时啦"))
    end
end

function FriendInvitationSend:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.FriendPVPPromptBeRefused, self.EventFriendPVPPromptBeRefused)
        self:StopTimer()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return FriendInvitationSend